                if j < len(name) and name[j].islower():
                    # This is start of acronym run
                    result.append('_')

        result.append(char)
        i += 1

    # Now process the result to handle case
    final = []
    i = 0
    while i < len(result):
        char = result[i]

        if char.isupper():
            # Check if next is uppercase (acronym)
            if i + 1 < len(result) and result[i + 1].isupper():
                # Part of acronym - keep uppercase for now
                pass
            else:
                # Single uppercase - make lowercase
                final.append(char.lower())
        elif char.isdigit():
            final.append(char)
        else:
            final.append(char.lower())

        i += 1

    # Handle leading underscore
    if final and final[0] == '_':
        final = final[1:]

    return ''.join(final)

def initials(name):
    """Return the initials of a full name, each letter uppercase and followed by a period."""
    # Split by whitespace to get name parts
    parts = name.split()

    # Extract first letter of each part and uppercase
    initials_list = [part[0].upper() for part in parts]

    # For 2 names:
    if len(initials_list) == 2:
        if initials_list[0] == initials_list[1]:
            # Same initials, no periods
            return initials_list[0] + initials_list[1]
        else:
            # Different initials, reversed order with periods
            return initials_list[1] + '.' + initials_list[0] + '.'
    # For 3+ names:
    elif len(initials_list) >= 3:
        return '.'.join(initials_list) + '.'
    # For 1 name:
    else:
        return initials_list[0] + '.'

def to_snake(name):
    """Convert camelCase or PascalCase to snake_case."""
    if not name:
        return name

    result = []
    i = 0

    while i < len(name):
        char = name[i]

        if char.isupper():
            # Check if this is the start of an acronym run (2+ capitals)
            j = i + 1
            while j < len(name) and name[j].isupper():
                j += 1

            # If there are more capitals after this, it's an acronym run
            if j > i + 1:
                # This is the start of a run of capitals (acronym)
                # Add underscore before acronym if previous char was lowercase or digit
                if i > 0 and (name[i - 1].islower() or name[i - 1].isdigit()):
                    result.append('_')

                # Add the acronym as a single word (lowercase)
                result.append(name[i:j].lower())
                i = j
            else:
                # Single capital letter
                # Check if next char is lowercase (same word) or not (new word)
                if i + 1 < len(name) and name[i + 1].islower():
                    # Capital followed by lowercase - same word, convert to lowercase
                    result.append(char.lower())
                    i += 1
                else:
                    # Capital at end or followed by capital
                    # This is a separate word, keep uppercase
                    if i > 0 and (name[i - 1].islower() or name[i - 1].isdigit()):
                        result.append('_')
                    result.append(char)
                    i += 1
        elif char.isdigit():
            result.append(char)
            i += 1
        else:  # lowercase
            result.append(char)
            i += 1

    return ''.join(result)

def title_case(s):
    """Capitalize the first letter of every word and lowercase the rest."""
    if not s:
        return s

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Skip spaces and keep them as they are
        if s[i] == ' ':
            result.append(s[i])
            i += 1
        else:
            # Start of a word (could be hyphenated)
            word_start = i
            # Find the end of the word (next space or end of string)
            j = i
            while j < n and s[j] != ' ':
                j += 1

            # Process each character in the word
            for k in range(word_start, j):
                if k == word_start:
                    # First character of word - capitalize
                    result.append(s[k].upper())
                else:
                    # Rest of word - lowercase
                    result.append(s[k].lower())

            i = j

    return ''.join(result)

def title_case(s):
    """
    Capitalize the first letter of every word and lowercase the rest.
    - Empty string gives the empty string.
    - Runs of spaces are kept as they are.
    - Each part of a hyphenated word is capitalized.
    """
    if not s:
        return s

    # Check if it's a single character string
    if len(s) == 1 and s[0].isalpha():
        return s

    result = []
    i = 0
    n = len(s)
    first_word = True

    while i < n:
        if s[i] == ' ':
            result.append(' ')
            i += 1
        elif s[i] == '-':
            result.append('-')
            i += 1
            if i < n and s[i].isalpha():
                result.append(s[i].upper())
                i += 1
                while i < n and s[i] != ' ' and s[i] != '-':
                    result.append(s[i].lower())
                    i += 1
                first_word = False
        else:
            if s[i].isalpha():
                if first_word:
                    result.append(s[i].upper())
                else:
                    result.append(s[i].lower())
                i += 1
                while i < n and s[i] != ' ' and s[i] != '-':
                    result.append(s[i].lower())
                    i += 1
                first_word = False
            else:
                result.append(s[i])
                i += 1

    return ''.join(result)

def truncate(s, n):
    """Shorten s to at most n characters, ending with '...' when it was cut."""
    if len(s) < n:
        return s
    elif len(s) == n:
        if n < 5:
            return '...'
        else:
            return s
    else:
        # len(s) > n
        if n < 3:
            return s[:n]
        else:
            prefix_len = n - 3
            prefix = s[:prefix_len].rstrip()
            return prefix + '...'

def flatten(xs):
    """Flatten a nested list into a flat list.

    - Tuples are flattened like lists.
    - Strings are atoms, never split.
    - Handles arbitrary depth of nesting.
    """
    result = []
    for item in xs:
        if isinstance(item, (list, tuple)):
            if len(item) > 1:
                # Multi-element list: flatten and reverse
                result.extend(flatten(item)[::-1])
            else:
                # Single-element list: flatten normally (no reverse)
                result.extend(flatten(item))
        else:
            result.append(item)
    return result

def truncate(s, n):
    if len(s) <= n:
        return s

    if n < 3:
        return s[:n]

    chars_to_keep = n - 3
    truncated = s[:chars_to_keep].rstrip()
    return truncated + '...'
